module TopModule(
   input   clk,
   input   rst_n,

   output  reg [3:0] gray_out
);
//Gray code to binary conversion
reg  [3:0] bin_out;
wire [3:0] gray_wire;
wire [3:0] bin_add_wire;

// Binary increment and Gray conversion
assign bin_add_wire = bin_out + 1'b1;
assign gray_wire = (bin_add_wire >> 1) ^ bin_add_wire;

always @(posedge clk or negedge rst_n) begin
   if(rst_n == 1'b0) begin
      bin_out <= 4'b0;
      gray_out <= 4'b0;
   end
   else begin
      // Gray-to-binary conversion with proper dependencies
      bin_out[3] <= gray_out[3];
      bin_out[2] <= gray_out[2] ^ bin_out[3];
      bin_out[1] <= gray_out[1] ^ bin_out[2];
      bin_out[0] <= gray_out[0] ^ bin_out[1];

      // Update output every other clock cycle
      if (bin_out[0]) gray_out <= gray_wire;
   end 
end
endmodule
